#include "fable_graphic_info.h"
#include <algorithm>
void CGraphicInfo::UnloadFrame(unsigned long frameIndex){unsigned long count=Header.FrameCount;if(count>1){frameIndex=~0UL;for(unsigned long index=0;index<count;++index){CGraphicInfoFrame& frame=Frames[index];if(!frame.Data.IsNull()&&!frame.Data->StopLoading())return;if(!frame.Data.IsNull()){unsigned long age=frame.Data->GetUnusedFrames();frameIndex=std::min(frameIndex,age);}}if(frameIndex>=Bank->UnloadFrameDelay){unsigned long index=0;while(count){CIVCountedPointer<CGraphicInfoFrame::CFrameData>& data=Frames[index].Data;data.Release();data.data_=0;++index;--count;}}}else{CGraphicInfoFrame& frame=Frames[frameIndex];if((frame.Data.IsNull()||frame.Data->StopLoading())&&!frame.Data.IsNull()){unsigned long age=frame.Data->GetUnusedFrames();if(!frame.Data.IsNull())frame.Data->FreeTextureMemory(age>=Bank->UnloadFrameDelay);}}}
